from collections import OrderedDict

class LRUCache:
    """Least Recently Used cache backed by OrderedDict."""

    def __init__(self, capacity):
        """Initialize cache with max capacity."""
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        """Get value for key, or None if not found. Marks key as recently used."""
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Put key-value pair in cache. Evicts LRU item if at capacity."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value

        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache


# Example usage
if __name__ == "__main__":
    lru = LRUCache(2)
    lru.put(1, "a")
    lru.put(2, "b")
    print(lru.get(1))  # "a" (marks 1 as recently used)
    lru.put(3, "c")   # Evicts key 2 (least recently used)
    print(lru.get(2))  # None
    print(lru.get(3))  # "c"
```

